    assertTrue(versionManager.isAllowed(lfs[1].name()));
    assertTrue(versionManager.isAllowed(lfs[1]));
    assertFalse(versionManager.isAllowed(lfs[2].name()));
    assertFalse(versionManager.isAllowed(lfs[2]));
}

