    inOrder.verify(finalizer).postFinalizeUpgrade(ArgumentMatchers.eq(mockObj));
    assertTrue(finalizer.isFinalizationDone());
    assertTrue(finalizer.preCalled && finalizer.finalizeCalled && finalizer.postCalled);
}

