    assertTrue(pipelineActions.isEmpty());
    // Add 2 scm endpoints.
    stateContext.addEndpoint(scm1);
    stateContext.addEndpoint(scm2);
    final ClosePipelineInfo closePipelineInfo = ClosePipelineInfo.newBuilder().setPipelineID(PipelineID.randomId().getProtobuf()).setReason(ClosePipelineInfo.Reason.PIPELINE_FAILED).setDetailedReason("Test").build();
    final PipelineAction pipelineAction = PipelineAction.newBuilder().setClosePipeline(closePipelineInfo).setAction(PipelineAction.Action.CLOSE).build();
    // Add PipelineAction. Should be added to all endpoints.
    stateContext.addPipelineActionIfAbsent(pipelineAction);
    pipelineActions = stateContext.getPendingPipelineAction(scm2, 10);
    assertEquals(1, pipelineActions.size());
    // The pipeline action is dequeued from scm2 now, but still in scm1
    // The same pipeline action will not be added if it already exists
    stateContext.addPipelineActionIfAbsent(pipelineAction);
    pipelineActions = stateContext.getPendingPipelineAction(scm1, 10);
    assertEquals(1, pipelineActions.size());
    // The pipeline action should have been be added back to the scm2
    pipelineActions = stateContext.getPendingPipelineAction(scm2, 10);
    assertEquals(1, pipelineActions.size());
    // Add ContainerAction. Should be added to all endpoints.
    stateContext.addContainerAction(ContainerAction.newBuilder().setAction(CLOSE).setContainerID(100L).build());
    containerActions = stateContext.getPendingContainerAction(scm2, 10);
    assertEquals(1, containerActions.size());
}

@Test
public void testGetReports() {
    OzoneConfiguration conf = new OzoneConfiguration();
    DatanodeStateMachine datanodeStateMachineMock = mock(DatanodeStateMachine.class);
    StateContext ctx = new StateContext(conf, DatanodeStates.getInitState(), datanodeStateMachineMock);
    InetSocketAddress scm1 = new InetSocketAddress("scm1", 9001);
    ctx.addEndpoint(scm1);
    InetSocketAddress scm2 = new InetSocketAddress("scm2", 9001);
    ctx.addEndpoint(scm2);
    // Check initial state
    assertEquals(0, ctx.getAllAvailableReports(scm1).size());
    assertEquals(0, ctx.getAllAvailableReports(scm2).size());
    Map<String, Integer> expectedReportCount = new HashMap<>();
    int totalIncrementalCount = 128;
    // Add a bunch of ContainerReports
    batchRefreshfullReports(ctx, StateContext.CONTAINER_REPORTS_PROTO_NAME, totalIncrementalCount);
    batchRefreshfullReports(ctx, StateContext.NODE_REPORT_PROTO_NAME, totalIncrementalCount);
    batchRefreshfullReports(ctx, StateContext.PIPELINE_REPORTS_PROTO_NAME, totalIncrementalCount);
    batchRefreshfullReports(ctx, StateContext.CRL_STATUS_REPORT_PROTO_NAME, totalIncrementalCount);
    batchAddIncrementalReport(ctx, StateContext.INCREMENTAL_CONTAINER_REPORT_PROTO_NAME, totalIncrementalCount);
    // Should only keep the latest one
    expectedReportCount.put(StateContext.CONTAINER_REPORTS_PROTO_NAME, 1);
    expectedReportCount.put(StateContext.NODE_REPORT_PROTO_NAME, 1);
    expectedReportCount.put(StateContext.PIPELINE_REPORTS_PROTO_NAME, 1);
    expectedReportCount.put(StateContext.CRL_STATUS_REPORT_PROTO_NAME, 1);
    // Should keep less or equal than maxLimit depending on other reports' size.
    // Here, the incremental container reports count must be 96
    // (100 - 4 non-incremental reports)
    expectedReportCount.put(StateContext.INCREMENTAL_CONTAINER_REPORT_PROTO_NAME, 96);
    checkReportCount(ctx.getAllAvailableReportsUpToLimit(scm1, 100), expectedReportCount);
    checkReportCount(ctx.getAllAvailableReportsUpToLimit(scm2, 100), expectedReportCount);
    expectedReportCount.clear();
    expectedReportCount.put(StateContext.INCREMENTAL_CONTAINER_REPORT_PROTO_NAME, totalIncrementalCount - 96);
    checkReportCount(ctx.getAllAvailableReportsUpToLimit(scm1, 100), expectedReportCount);
    checkReportCount(ctx.getAllAvailableReportsUpToLimit(scm2, 100), expectedReportCount);
}

