@Test
public void testDiskFullExceptionCreateContainer() throws Exception {
    Mockito.when(volumeChoosingPolicy.chooseVolume(anyList(), anyLong())).thenThrow(DiskChecker.DiskOutOfSpaceException.class);
    try {
        keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
        fail("testDiskFullExceptionCreateContainer failed");
