@Test
public void testSameContainerQueuedMultipleTimes() throws Exception {
    OnDemandContainerScanner.init(conf, controller);
    //Given a container that has not finished scanning
    CountDownLatch latch = new CountDownLatch(1);
    Mockito.lenient().when(corruptData.scanData(OnDemandContainerScanner.getThrottler(), OnDemandContainerScanner.getCanceler())).thenAnswer((Answer<Boolean>) invocation -> {
        latch.await();
        return false;
    });
    Optional<Future<?>> onGoingScan = OnDemandContainerScanner.scanContainer(corruptData);
    Assert.assertTrue(onGoingScan.isPresent());
    Assert.assertFalse(onGoingScan.get().isDone());
    //When scheduling the same container again
    Optional<Future<?>> secondScan = OnDemandContainerScanner.scanContainer(corruptData);
    //Then the second scan is not scheduled and the first scan can still finish
    Assert.assertFalse(secondScan.isPresent());
    latch.countDown();
    onGoingScan.get().get();
    Mockito.verify(controller, atLeastOnce()).markContainerUnhealthy(corruptData.getContainerData().getContainerID());
}

