public void testDownloadAndImportReplicatorFailure() throws IOException {
    ReplicationSupervisor supervisor = new ReplicationSupervisor(context, newDirectExecutorService(), clock);
    OzoneConfiguration conf = new OzoneConfiguration();
    // Mock to fetch an exception in the importContainer method.
    SimpleContainerDownloader moc = Mockito.mock(SimpleContainerDownloader.class);
    Path res = Paths.get("file:/tmp/no-such-file");
    Mockito.when(moc.getContainerDataFromReplicas(Mockito.anyLong(), Mockito.anyList(), Mockito.any(Path.class))).thenReturn(res);
    final String testDir = GenericTestUtils.getTempPath(TestReplicationSupervisor.class.getSimpleName() + "-" + UUID.randomUUID().toString());
