    Mockito.when(volumeSet.getVolumesList()).thenReturn(Collections.singletonList(new HddsVolume.Builder(testDir).conf(conf).build()));
    ContainerImporter importer = new ContainerImporter(conf, set, null, null, volumeSet);
    ContainerReplicator replicator = new DownloadAndImportReplicator(set, importer, moc);
    replicatorRef.set(replicator);
    GenericTestUtils.LogCapturer logCapturer = GenericTestUtils.LogCapturer.captureLogs(DownloadAndImportReplicator.LOG);
    supervisor.addTask(createTask(1L));
    Assert.assertEquals(1, supervisor.getReplicationFailureCount());
    Assert.assertEquals(0, supervisor.getReplicationSuccessCount());
    Assert.assertTrue(logCapturer.getOutput().contains("Container 1 replication was unsuccessful."));
}

