@Test
public void testFinalizeFailure() throws Exception {
    // start DN and SCM
    startScmServer();
    addHddsVolume();
    // Let HddsVolume be formatted to mimic the real cluster upgrade
    // Set layout version.
    DatanodeLayoutStorage layoutStorage = new DatanodeLayoutStorage(conf, UUID.randomUUID().toString(), HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion());
    layoutStorage.initialize();
    dsm = new DatanodeStateMachine(ContainerTestUtils.createDatanodeDetails(), conf, null, null, null);
    HddsVolume dataVolume = (HddsVolume) dsm.getContainer().getVolumeSet().getVolumesList().get(0);
    // Format HddsVolume to mimic the real cluster upgrade situation
    dataVolume.format(CLUSTER_ID);
    File idDir = new File(dataVolume.getStorageDir(), CLUSTER_ID);
    if (!idDir.mkdir()) {
        Assert.fail("Failed to create id directory");
    }
    Assert.assertNull(dataVolume.getDbParentDir());
    // Restart DN
    restartDatanode(HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion(), true);
    // Write some data.
    final Pipeline pipeline = getPipeline();
    final long containerID = addContainer(pipeline);
    ContainerProtos.WriteChunkRequestProto writeChunk = putBlock(containerID, pipeline);
    closeContainer(containerID, pipeline);
    KeyValueContainer container = (KeyValueContainer) dsm.getContainer().getContainerSet().getContainer(containerID);
    Assert.assertEquals(OzoneConsts.SCHEMA_V2, container.getContainerData().getSchemaVersion());
    HddsVolume volume = Mockito.mock(HddsVolume.class);
    Mockito.doThrow(new IOException("Failed to init DB")).when(volume).createDbStore(anyObject());
    Map volumeMap = new HashMap<String, StorageVolume>();
    volumeMap.put(dataVolume.getStorageID(), volume);
    dsm.getContainer().getVolumeSet().setVolumeMap(volumeMap);
    // Finalize will fail because of DB creation failure
    try {
        dsm.finalizeUpgrade();
    } catch (Exception e) {
        // Currently there will be retry if finalization failed.
        // Let's assume retry is terminated by user.
    }
    // Check that old data is readable
    container = (KeyValueContainer) dsm.getContainer().getContainerSet().getContainer(containerID);
    Assert.assertEquals(OzoneConsts.SCHEMA_V2, container.getContainerData().getSchemaVersion());
    readChunk(writeChunk, pipeline);
    // SchemaV3 is not finalized, so still ERASURE_CODED_STORAGE_SUPPORT
    restartDatanode(HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion(), true);
    // Old data is readable after DN restart
    container = (KeyValueContainer) dsm.getContainer().getContainerSet().getContainer(containerID);
    Assert.assertEquals(OzoneConsts.SCHEMA_V2, container.getContainerData().getSchemaVersion());
    readChunk(writeChunk, pipeline);
}

