@Test
public void checkIterationResult() throws NodeNotFoundException, IOException, IllegalContainerBalancerStateException, InvalidContainerBalancerConfigurationException, TimeoutException {
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setIterations(1);
    balancerConfiguration.setMaxSizeEnteringTarget(10 * STORAGE_UNIT);
    balancerConfiguration.setMaxSizeToMovePerIteration(100 * STORAGE_UNIT);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    startBalancer(balancerConfiguration);
    /*
    According to the setup and configurations, this iteration's result should
    be ITERATION_COMPLETED.
     */
    Assertions.assertEquals(ContainerBalancerTask.IterationResult.ITERATION_COMPLETED, containerBalancerTask.getIterationResult());
    stopBalancer();
    /*
    Now, limit maxSizeToMovePerIteration but fail all container moves. The
    result should still be ITERATION_COMPLETED.
     */
    Mockito.when(replicationManager.move(Mockito.any(ContainerID.class), Mockito.any(DatanodeDetails.class), Mockito.any(DatanodeDetails.class))).thenReturn(CompletableFuture.completedFuture(MoveResult.REPLICATION_FAIL_NODE_UNHEALTHY));
    balancerConfiguration.setMaxSizeToMovePerIteration(10 * STORAGE_UNIT);
    startBalancer(balancerConfiguration);
    Assertions.assertEquals(ContainerBalancerTask.IterationResult.ITERATION_COMPLETED, containerBalancerTask.getIterationResult());
    stopBalancer();
}

