@Test
public void testMisReplicatedFixedByPending() {
    Mockito.when(containerPlacementPolicy.validateContainerPlacement(Mockito.any(), Mockito.anyInt())).thenAnswer(invocation -> {
        List<DatanodeDetails> dns = invocation.getArgument(0);
        // If the number of DNs is 3 or less make it be mis-replicated
        if (dns.size() <= 3) {
            return new ContainerPlacementStatusDefault(1, 2, 3);
        } else {
            return new ContainerPlacementStatusDefault(2, 2, 3);
        }
    });
    ContainerInfo container = createContainerInfo(repConfig);
    Set<ContainerReplica> replicas = createReplicas(container.containerID(), 0, 0, 0);
    List<ContainerReplicaOp> pending = new ArrayList<>();
    pending.add(ContainerReplicaOp.create(ADD, MockDatanodeDetails.randomDatanodeDetails(), 0));
    pending.add(ContainerReplicaOp.create(ADD, MockDatanodeDetails.randomDatanodeDetails(), 0));
    requestBuilder.setContainerReplicas(replicas).setContainerInfo(container).setPendingOps(pending);
    MisReplicatedHealthResult result = (MisReplicatedHealthResult) healthCheck.checkHealth(requestBuilder.build());
    Assert.assertEquals(HealthState.MIS_REPLICATED, result.getHealthState());
    Assert.assertTrue(result.isReplicatedOkAfterPending());
    Assert.assertTrue(healthCheck.handle(requestBuilder.build()));
    Assert.assertEquals(0, repQueue.underReplicatedQueueSize());
    Assert.assertEquals(0, repQueue.overReplicatedQueueSize());
    Assert.assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    Assert.assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.MIS_REPLICATED));
}

