private void testOverReplicationWithIndexes(Set<ContainerReplica> availableReplicas, Map<Integer, Integer> index2excessNum, List<ContainerReplicaOp> pendingOps) {
    ECOverReplicationHandler ecORH = new ECOverReplicationHandler(policy, nodeManager);
    ContainerHealthResult.OverReplicatedHealthResult result = Mockito.mock(ContainerHealthResult.OverReplicatedHealthResult.class);
    Mockito.when(result.getContainerInfo()).thenReturn(container);
    Set<Pair<DatanodeDetails, SCMCommand<?>>> commands = ecORH.processAndCreateCommands(availableReplicas, pendingOps, result, 1);
    // total commands send out should be equal to the sum of all
    // the excess nums
    int totalDeleteCommandNum = index2excessNum.values().stream().reduce(0, Integer::sum);
    Assert.assertEquals(totalDeleteCommandNum, commands.size());
    // Each command should have a non-zero replica index
    commands.forEach(pair -> Assert.assertNotEquals(0, ((DeleteContainerCommand) pair.getValue()).getReplicaIndex()));
    // command num of each index should be equal to the excess num
    // of this index
    Map<DatanodeDetails, Integer> datanodeDetails2Index = availableReplicas.stream().collect(Collectors.toMap(ContainerReplica::getDatanodeDetails, ContainerReplica::getReplicaIndex));
    Map<Integer, Integer> index2commandNum = new HashMap<>();
    commands.forEach(pair -> index2commandNum.merge(datanodeDetails2Index.get(pair.getKey()), 1, Integer::sum));
    index2commandNum.keySet().forEach(i -> {
        Assert.assertTrue(index2excessNum.containsKey(i));
        Assert.assertEquals(index2commandNum.get(i), index2excessNum.get(i));
    });
}

