public Set<Pair<DatanodeDetails, SCMCommand<?>>> testUnderReplicationWithMissingIndexes(List<Integer> missingIndexes, Set<ContainerReplica> availableReplicas, int decomIndexes, int maintenanceIndexes, PlacementPolicy placementPolicy) throws IOException {
    ECUnderReplicationHandler ecURH = new ECUnderReplicationHandler(placementPolicy, conf, nodeManager, replicationManager);
    ContainerHealthResult.UnderReplicatedHealthResult result = Mockito.mock(ContainerHealthResult.UnderReplicatedHealthResult.class);
    Mockito.when(result.isUnrecoverable()).thenReturn(false);
    Mockito.when(result.getContainerInfo()).thenReturn(container);
    Set<Pair<DatanodeDetails, SCMCommand<?>>> commands = ecURH.processAndCreateCommands(availableReplicas, ImmutableList.of(), result, remainingMaintenanceRedundancy);
    int replicateCommand = 0;
    int reconstructCommand = 0;
    byte[] missingIndexesByteArr = new byte[missingIndexes.size()];
    for (int i = 0; i < missingIndexes.size(); i++) {
        missingIndexesByteArr[i] = missingIndexes.get(i).byteValue();
    }
    boolean shouldReconstructCommandExist = missingIndexes.size() > 0 && missingIndexes.size() <= repConfig.getParity();
    for (Map.Entry<DatanodeDetails, SCMCommand<?>> dnCommand : commands) {
        if (dnCommand.getValue() instanceof ReplicateContainerCommand) {
            replicateCommand++;
        } else if (dnCommand.getValue() instanceof ReconstructECContainersCommand) {
            if (shouldReconstructCommandExist) {
                Assertions.assertArrayEquals(missingIndexesByteArr, ((ReconstructECContainersCommand) dnCommand.getValue()).getMissingContainerIndexes());
            }
            reconstructCommand++;
        }
    }
    int maxMaintenance = PARITY - remainingMaintenanceRedundancy;
    int expectedMaintenanceCommands = Math.max(0, maintenanceIndexes - maxMaintenance);
    Assertions.assertEquals(decomIndexes + expectedMaintenanceCommands, replicateCommand);
    Assertions.assertEquals(shouldReconstructCommandExist ? 1 : 0, reconstructCommand);
    return commands;
}

public Set<Pair<DatanodeDetails, SCMCommand<?>>> testUnderReplicationWithMissingIndexes(List<Integer> missingIndexes, Set<ContainerReplica> availableReplicas, int decomIndexes, int maintenanceIndexes, PlacementPolicy placementPolicy) throws IOException {
    ECUnderReplicationHandler ecURH = new ECUnderReplicationHandler(placementPolicy, conf, nodeManager, replicationManager);
    ContainerHealthResult.UnderReplicatedHealthResult result = Mockito.mock(ContainerHealthResult.UnderReplicatedHealthResult.class);
    Mockito.when(result.isUnrecoverable()).thenReturn(false);
    Mockito.when(result.getContainerInfo()).thenReturn(container);
    Set<Pair<DatanodeDetails, SCMCommand<?>>> commands = ecURH.processAndCreateCommands(availableReplicas, ImmutableList.of(), result, remainingMaintenanceRedundancy);
    int replicateCommand = 0;
    int reconstructCommand = 0;
    byte[] missingIndexesByteArr = new byte[missingIndexes.size()];
    for (int i = 0; i < missingIndexes.size(); i++) {
        missingIndexesByteArr[i] = missingIndexes.get(i).byteValue();
    }
    boolean shouldReconstructCommandExist = missingIndexes.size() > 0 && missingIndexes.size() <= repConfig.getParity();
    for (Map.Entry<DatanodeDetails, SCMCommand<?>> dnCommand : commands) {
        if (dnCommand.getValue() instanceof ReplicateContainerCommand) {
            replicateCommand++;
        } else if (dnCommand.getValue() instanceof ReconstructECContainersCommand) {
            if (shouldReconstructCommandExist) {
                Assertions.assertArrayEquals(missingIndexesByteArr, ((ReconstructECContainersCommand) dnCommand.getValue()).getMissingContainerIndexes());
            }
            reconstructCommand++;
        }
    }
    int maxMaintenance = PARITY - remainingMaintenanceRedundancy;
    int expectedMaintenanceCommands = Math.max(0, maintenanceIndexes - maxMaintenance);
    Assertions.assertEquals(decomIndexes + expectedMaintenanceCommands, replicateCommand);
    Assertions.assertEquals(shouldReconstructCommandExist ? 1 : 0, reconstructCommand);
    return commands;
}

