@Test
public void testUnderRepDueToDecomAndOverRep() throws IOException {
    PlacementPolicy sameNodePolicy = ReplicationTestUtil.getNoNodesTestPlacementPolicy(nodeManager, conf);
    // First it is under-replicated, due to decom index 5, but no mode will be
    // found. This will cause an exception to be thrown out, as the container is
    // not also over replicated.
    Set<ContainerReplica> availableReplicas = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3), Pair.of(IN_SERVICE, 4), Pair.of(DECOMMISSIONING, 5));
    ECUnderReplicationHandler ecURH = new ECUnderReplicationHandler(sameNodePolicy, conf, nodeManager, replicationManager);
    ContainerHealthResult.UnderReplicatedHealthResult underRep = new ContainerHealthResult.UnderReplicatedHealthResult(container, 1, true, false, false);
    Assert.assertThrows(SCMException.class, () -> ecURH.processAndCreateCommands(availableReplicas, Collections.emptyList(), underRep, 1));
    // Now adjust replicas so it is also over replicated. This time rather than
    // throwing it should call the OverRepHandler and return whatever it
    // returns, which in this case is a delete command for replica index 4.
    ContainerReplica overRepReplica = ReplicationTestUtil.createContainerReplica(container.containerID(), 4, IN_SERVICE, CLOSED);
    availableReplicas.add(overRepReplica);
    Set<Pair<DatanodeDetails, SCMCommand<?>>> expectedDelete = new HashSet<>();
    expectedDelete.add(Pair.of(overRepReplica.getDatanodeDetails(), createDeleteContainerCommand(container, overRepReplica)));
    Mockito.when(replicationManager.processOverReplicatedContainer(underRep)).thenReturn(expectedDelete);
    Set<Pair<DatanodeDetails, SCMCommand<?>>> commands = ecURH.processAndCreateCommands(availableReplicas, Collections.emptyList(), underRep, 1);
    Mockito.verify(replicationManager, times(1)).processOverReplicatedContainer(underRep);
    Assertions.assertEquals(true, expectedDelete.equals(commands));
}

