/**
 * 2 open replicas.
 * 1 unhealthy replica.
 * Expectation: Container is closed.
 *
 * ReplicationManager should close the unhealthy OPEN container.
 */
@Test
public void testUnhealthyOpenContainer() throws IOException, TimeoutException {
    final ContainerInfo container = getContainer(LifeCycleState.OPEN);
    final ContainerID id = container.containerID();
    final Set<ContainerReplica> replicas = getReplicas(id, State.OPEN, randomDatanodeDetails(), randomDatanodeDetails());
    replicas.addAll(getReplicas(id, UNHEALTHY, randomDatanodeDetails()));
    containerStateManager.addContainer(container.getProtobuf());
    for (ContainerReplica replica : replicas) {
        containerStateManager.updateContainerReplica(id, replica);
    }
    final CloseContainerEventHandler closeContainerHandler = Mockito.mock(CloseContainerEventHandler.class);
    eventQueue.addHandler(SCMEvents.CLOSE_CONTAINER, closeContainerHandler);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    Mockito.verify(closeContainerHandler, Mockito.times(1)).onMessage(id, eventQueue);
    ReplicationManagerReport report = replicationManager.getContainerReport();
    Assertions.assertEquals(1, report.getStat(LifeCycleState.OPEN));
    Assertions.assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.OPEN_UNHEALTHY));
}

