protected void testMisReplication(Set<ContainerReplica> availableReplicas, PlacementPolicy mockedPlacementPolicy, List<ContainerReplicaOp> pendingOp, int maintenanceCnt, int misreplicationCount, int expectedNumberOfNodes) throws IOException {
    MisReplicationHandler misReplicationHandler = getMisreplicationHandler(mockedPlacementPolicy, conf, nodeManager);
    ContainerHealthResult.MisReplicatedHealthResult result = Mockito.mock(ContainerHealthResult.MisReplicatedHealthResult.class);
    Mockito.when(result.isReplicatedOkAfterPending()).thenReturn(false);
    Mockito.when(result.getContainerInfo()).thenReturn(container);
    Map<ContainerReplica, Boolean> sources = availableReplicas.stream().collect(Collectors.toMap(Function.identity(), r -> {
        if (r.getDatanodeDetails().getPersistedOpState() == IN_SERVICE) {
            try {
                return nodeManager.getNodeStatus(r.getDatanodeDetails()).isHealthy();
            } catch (NodeNotFoundException e) {
                throw new RuntimeException(e);
            }
        }
        return false;
    }));
    Set<ContainerReplica> copy = sources.entrySet().stream().filter(Map.Entry::getValue).limit(misreplicationCount).map(Map.Entry::getKey).collect(Collectors.toSet());
    Mockito.when(mockedPlacementPolicy.replicasToCopyToFixMisreplication(anyMap())).thenAnswer(invocation -> copy);
    Set<DatanodeDetails> remainingReplicasAfterCopy = availableReplicas.stream().filter(r -> !copy.contains(r)).map(ContainerReplica::getDatanodeDetails).collect(Collectors.toSet());
    List<DatanodeDetails> targetNodes = IntStream.range(0, expectedNumberOfNodes).mapToObj(i -> MockDatanodeDetails.randomDatanodeDetails()).collect(Collectors.toList());
    if (expectedNumberOfNodes > 0) {
        Mockito.when(mockedPlacementPolicy.chooseDatanodes(Mockito.any(), Mockito.any(), Mockito.any(), eq(copy.size()), Mockito.anyLong(), Mockito.anyLong())).thenAnswer(invocation -> {
            List<DatanodeDetails> datanodeDetails = invocation.getArgument(0);
            Assertions.assertTrue(remainingReplicasAfterCopy.containsAll(datanodeDetails));
            return targetNodes;
        });
    }
    Map<DatanodeDetails, Integer> copyReplicaIdxMap = copy.stream().collect(Collectors.toMap(ContainerReplica::getDatanodeDetails, ContainerReplica::getReplicaIndex));
    Set<Pair<DatanodeDetails, SCMCommand<?>>> commands = misReplicationHandler.processAndCreateCommands(availableReplicas, pendingOp, result, maintenanceCnt);
    Assertions.assertEquals(expectedNumberOfNodes, commands.size());
    Assertions.assertEquals(new HashSet<>(targetNodes), commands.stream().map(Pair::getKey).collect(Collectors.toSet()));
    for (Pair<DatanodeDetails, SCMCommand<?>> pair : commands) {
        SCMCommand<?> command = pair.getValue();
        Assertions.assertTrue(command.getType() == replicateContainerCommand);
        ReplicateContainerCommand replicateContainerCommand = (ReplicateContainerCommand) command;
        Assertions.assertEquals(replicateContainerCommand.getContainerID(), container.getContainerID());
        DatanodeDetails replicateSrcDn = replicateContainerCommand.getSourceDatanodes().stream().findFirst().get();
        Assertions.assertTrue(copyReplicaIdxMap.containsKey(replicateSrcDn));
        Assertions.assertEquals(copyReplicaIdxMap.get(replicateSrcDn), replicateContainerCommand.getReplicaIndex());
    }
}

