@Test
public void testEcReconstructionCommand() throws IOException {
    ContainerInfo container = ReplicationTestUtil.createContainer(HddsProtos.LifeCycleState.CLOSED, repConfig);
    Mockito.when(replicationManager.dequeueUnderReplicatedContainer()).thenReturn(new ContainerHealthResult.UnderReplicatedHealthResult(container, 3, false, false, false), (ContainerHealthResult.UnderReplicatedHealthResult) null);
    List<ReconstructECContainersCommand.DatanodeDetailsAndReplicaIndex> sourceNodes = new ArrayList<>();
    for (int i = 1; i <= 3; i++) {
        sourceNodes.add(new ReconstructECContainersCommand.DatanodeDetailsAndReplicaIndex(MockDatanodeDetails.randomDatanodeDetails(), i));
    }
    List<DatanodeDetails> targetNodes = new ArrayList<>();
    targetNodes.add(MockDatanodeDetails.randomDatanodeDetails());
    targetNodes.add(MockDatanodeDetails.randomDatanodeDetails());
    byte[] missingIndexes = { 4, 5 };
    Set<Pair<DatanodeDetails, SCMCommand<?>>> commands = new HashSet<>();
    commands.add(Pair.of(MockDatanodeDetails.randomDatanodeDetails(), new ReconstructECContainersCommand(container.getContainerID(), sourceNodes, targetNodes, missingIndexes, repConfig)));
    Mockito.when(replicationManager.processUnderReplicatedContainer(any())).thenReturn(commands);
    underReplicatedProcessor.processAll();
    Mockito.verify(replicationManager, Mockito.times(1)).sendDatanodeCommand(any(), any(), any());
    Mockito.verify(replicationManager, Mockito.times(0)).requeueUnderReplicatedContainer(any());
}

