@Test
public void openContainerKeyAndBytesUsedUpdatedToMinimumOfAllReplicas() throws IOException, TimeoutException {
    final ContainerReportHandler reportHandler = new ContainerReportHandler(nodeManager, containerManager);
    final Iterator<DatanodeDetails> nodeIterator = nodeManager.getNodes(NodeStatus.inServiceHealthy()).iterator();
    Pipeline pipeline = pipelineManager.createPipeline(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE));
    final DatanodeDetails datanodeOne = nodeIterator.next();
    final DatanodeDetails datanodeTwo = nodeIterator.next();
    final DatanodeDetails datanodeThree = nodeIterator.next();
    final ContainerReplicaProto.State replicaState = ContainerReplicaProto.State.OPEN;
    final ContainerInfo containerOne = getContainer(LifeCycleState.OPEN, pipeline.getId());
    containerStateManager.addContainer(containerOne.getProtobuf());
    // Container loaded, no replicas reported from DNs. Expect zeros for
    // usage values.
    assertEquals(0L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(0L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, datanodeOne, 50L, 60L), publisher);
    // Single replica reported - ensure values are updated
    assertEquals(50L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(60L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, datanodeTwo, 50L, 60L), publisher);
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, datanodeThree, 50L, 60L), publisher);
    // All 3 DNs are reporting the same values. Counts should be as expected.
    assertEquals(50L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(60L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    // Now each DN reports a different lesser value. Counts should be the min
    // reported.
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, datanodeOne, 1L, 10L), publisher);
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, datanodeTwo, 2L, 11L), publisher);
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, datanodeThree, 3L, 12L), publisher);
    // All 3 DNs are reporting different values. The actual value should be the
    // minimum.
    assertEquals(1L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(10L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    // Have the lowest value report a higher value and ensure the new value
    // is the minimum
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, datanodeOne, 3L, 12L), publisher);
    assertEquals(2L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(11L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
}

