@Test
public void testHAWithSamePortConfig() throws Exception {
    String scmServiceId = "scmserviceId";
    conf.set(ScmConfigKeys.OZONE_SCM_SERVICE_IDS_KEY, scmServiceId);
    String[] nodes = new String[] { "scm1", "scm2", "scm3" };
    conf.set(ScmConfigKeys.OZONE_SCM_NODES_KEY + "." + scmServiceId, "scm1,scm2,scm3");
    conf.set(ScmConfigKeys.OZONE_SCM_NODE_ID_KEY, "scm1");
    for (String node : nodes) {
        conf.set(ConfUtils.addKeySuffixes(OZONE_SCM_ADDRESS_KEY, scmServiceId, node), "localhost");
    }
    conf.set(OZONE_SCM_RATIS_PORT_KEY, "10000");
    conf.set(OZONE_SCM_GRPC_PORT_KEY, "10001");
    conf.set(OZONE_SCM_BLOCK_CLIENT_PORT_KEY, "9896");
    conf.set(OZONE_SCM_CLIENT_PORT_KEY, "9897");
    conf.set(OZONE_SCM_DATANODE_PORT_KEY, "9898");
    conf.set(OZONE_SCM_SECURITY_SERVICE_PORT_KEY, "9899");
    SCMStorageConfig scmStorageConfig = Mockito.mock(SCMStorageConfig.class);
    Mockito.when(scmStorageConfig.getState()).thenReturn(Storage.StorageState.NOT_INITIALIZED);
    SCMHANodeDetails scmhaNodeDetails = SCMHANodeDetails.loadSCMHAConfig(conf, scmStorageConfig);
    Assertions.assertEquals("10000", conf.get(OZONE_SCM_RATIS_PORT_KEY));
    Assertions.assertEquals("10001", conf.get(OZONE_SCM_GRPC_PORT_KEY));
    InetSocketAddress clientAddress = NetUtils.createSocketAddr("0.0.0.0", 9897);
    InetSocketAddress blockAddress = NetUtils.createSocketAddr("0.0.0.0", 9896);
    InetSocketAddress datanodeAddress = NetUtils.createSocketAddr("0.0.0.0", 9898);
    Assertions.assertEquals(clientAddress, scmhaNodeDetails.getLocalNodeDetails().getClientProtocolServerAddress());
    Assertions.assertEquals(blockAddress, scmhaNodeDetails.getLocalNodeDetails().getBlockProtocolServerAddress());
    Assertions.assertEquals(datanodeAddress, scmhaNodeDetails.getLocalNodeDetails().getDatanodeProtocolServerAddress());
    Assertions.assertEquals(10000, scmhaNodeDetails.getLocalNodeDetails().getRatisPort());
    Assertions.assertEquals(10001, scmhaNodeDetails.getLocalNodeDetails().getGrpcPort());
    for (SCMNodeDetails peer : scmhaNodeDetails.getPeerNodeDetails()) {
        Assertions.assertEquals(clientAddress, peer.getClientProtocolServerAddress());
        Assertions.assertEquals(blockAddress, peer.getBlockProtocolServerAddress());
        Assertions.assertEquals(datanodeAddress, peer.getDatanodeProtocolServerAddress());
        Assertions.assertEquals(10000, peer.getRatisPort());
        Assertions.assertEquals(10001, peer.getGrpcPort());
    }
    // Security protocol address is not set in SCMHANode Details.
    // Check conf is properly set with expected port.
    Assertions.assertEquals(NetUtils.createSocketAddr("0.0.0.0", 9899), HddsServerUtil.getScmSecurityInetAddress(conf));
}

