@Test
public void testMaintenanceEndsWhileReplicatingContainers() throws ContainerNotFoundException, NodeNotFoundException {
    DatanodeDetails dn1 = MockDatanodeDetails.randomDatanodeDetails();
    nodeManager.register(dn1, new NodeStatus(ENTERING_MAINTENANCE, HddsProtos.NodeState.HEALTHY));
    nodeManager.setContainers(dn1, generateContainers(3));
    DatanodeAdminMonitorTestUtil.mockGetContainerReplicaCount(repManager, HddsProtos.LifeCycleState.CLOSED, IN_MAINTENANCE, ENTERING_MAINTENANCE, IN_MAINTENANCE);
    // Add the node to the monitor, it should transiting to
    // REPLICATE_CONTAINERS as the containers are under-replicated for
    // maintenance.
    monitor.startMonitoring(dn1);
    monitor.run();
    assertEquals(1, monitor.getTrackedNodeCount());
    DatanodeDetails node = getFirstTrackedNode();
    assertTrue(nodeManager.getNodeStatus(dn1).isEnteringMaintenance());
