@Test
public void testOnMessage() throws Exception {
    //GIVEN
    DatanodeDetails datanode1 = MockDatanodeDetails.randomDatanodeDetails();
    DatanodeDetails datanode2 = MockDatanodeDetails.randomDatanodeDetails();
    DatanodeDetails datanode3 = MockDatanodeDetails.randomDatanodeDetails();
    String storagePath = GenericTestUtils.getRandomizedTempPath().concat("/data-" + datanode1.getUuidString());
    String metaStoragePath = GenericTestUtils.getRandomizedTempPath().concat("/metadata-" + datanode1.getUuidString());
    StorageReportProto storageOne = HddsTestUtils.createStorageReport(datanode1.getUuid(), storagePath, 100 * OzoneConsts.TB, 10 * OzoneConsts.TB, 90 * OzoneConsts.TB, null);
    MetadataStorageReportProto metaStorageOne = HddsTestUtils.createMetadataStorageReport(metaStoragePath, 100 * OzoneConsts.GB, 10 * OzoneConsts.GB, 90 * OzoneConsts.GB, null);
    // Exit safemode, as otherwise the safemode precheck will prevent pipelines
    // from getting created. Due to how this test is wired up, safemode will
    // not exit when the DNs are registered directly with the node manager.
    scm.exitSafeMode();
    // Standalone pipeline now excludes the nodes which are already used,
    // is the a proper behavior. Adding 9 datanodes for now to make the
    // test case happy.
    nodeManager.register(datanode1, HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(datanode2, HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(datanode3, HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), HddsTestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    LambdaTestUtils.await(120000, 1000, () -> pipelineManager.getPipelines(RatisReplicationConfig.getInstance(THREE)).size() > 3);
    HddsTestUtils.openAllRatisPipelines(pipelineManager);
    ContainerInfo container1 = HddsTestUtils.allocateContainer(containerManager);
    ContainerInfo container2 = HddsTestUtils.allocateContainer(containerManager);
    ContainerInfo container3 = HddsTestUtils.allocateContainer(containerManager);
    ContainerInfo container4 = HddsTestUtils.allocateContainer(containerManager);
    registerContainers(datanode1, container1, container2, container4);
    registerContainers(datanode2, container1, container2);
    registerContainers(datanode3, container3);
    registerReplicas(containerManager, container1, datanode1, datanode2);
    registerReplicas(containerManager, container2, datanode1, datanode2);
    registerReplicas(containerManager, container3, datanode3);
    registerReplicas(containerManager, container4, datanode1);
    HddsTestUtils.closeContainer(containerManager, container1.containerID());
    HddsTestUtils.closeContainer(containerManager, container2.containerID());
    HddsTestUtils.quasiCloseContainer(containerManager, container3.containerID());
    // First set the node to IN_MAINTENANCE and ensure the container replicas
    // are not removed on the dead event
    datanode1 = nodeManager.getNodeByUuid(datanode1.getUuidString());
    Assertions.assertTrue(nodeManager.getClusterNetworkTopologyMap().contains(datanode1));
    nodeManager.setNodeOperationalState(datanode1, HddsProtos.NodeOperationalState.IN_MAINTENANCE);
    deadNodeHandler.onMessage(datanode1, publisher);
    // make sure the node is removed from
    // ClusterNetworkTopology when it is considered as dead
    Assertions.assertFalse(nodeManager.getClusterNetworkTopologyMap().contains(datanode1));
    Set<ContainerReplica> container1Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container1.getContainerID()));
    Assertions.assertEquals(2, container1Replicas.size());
    Set<ContainerReplica> container2Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container2.getContainerID()));
    Assertions.assertEquals(2, container2Replicas.size());
    Set<ContainerReplica> container3Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container3.getContainerID()));
    Assertions.assertEquals(1, container3Replicas.size());
    // Now set the node to anything other than IN_MAINTENANCE and the relevant
    // replicas should be removed
    nodeManager.setNodeOperationalState(datanode1, HddsProtos.NodeOperationalState.IN_SERVICE);
    deadNodeHandler.onMessage(datanode1, publisher);
    //datanode1 has been removed from ClusterNetworkTopology, another
    //deadNodeHandler.onMessage call will not change this
    Assertions.assertFalse(nodeManager.getClusterNetworkTopologyMap().contains(datanode1));
    container1Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container1.getContainerID()));
    Assertions.assertEquals(1, container1Replicas.size());
    Assertions.assertEquals(datanode2, container1Replicas.iterator().next().getDatanodeDetails());
    container2Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container2.getContainerID()));
    Assertions.assertEquals(1, container2Replicas.size());
    Assertions.assertEquals(datanode2, container2Replicas.iterator().next().getDatanodeDetails());
    container3Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container3.getContainerID()));
    Assertions.assertEquals(1, container3Replicas.size());
    Assertions.assertEquals(datanode3, container3Replicas.iterator().next().getDatanodeDetails());
    //datanode will be added back to ClusterNetworkTopology if it resurrects
    healthyReadOnlyNodeHandler.onMessage(datanode1, publisher);
    Assertions.assertTrue(nodeManager.getClusterNetworkTopologyMap().contains(datanode1));
}

