 */
@Test
public void testDecommMonitorCollectSufficientlyReplicated() throws ContainerNotFoundException, NodeNotFoundException {
    DatanodeDetails dn1 = MockDatanodeDetails.createDatanodeDetails("datanode_host1", "/r1/ng1");
    nodeManager.register(dn1, new NodeStatus(DECOMMISSIONING, HddsProtos.NodeState.HEALTHY));
    Set<ContainerID> containers = new HashSet<>();
    containers.add(ContainerID.valueOf(1));
    // create container with 3 replicas,
    // all in-service
    nodeManager.setContainers(dn1, containers);
    DatanodeAdminMonitorTestUtil.mockGetContainerReplicaCount(repManager, HddsProtos.LifeCycleState.CLOSED, IN_SERVICE, IN_SERVICE, IN_SERVICE);
    monitor.startMonitoring(dn1);
    monitor.run();
    // expect dn in decommissioning workflow with container
    // sufficiently replicated
    Assertions.assertEquals(1, metrics.getContainersSufficientlyReplicatedTotal());
    // should have host specific metric collected
    // for datanode_host1
    Assertions.assertEquals(1, metrics.getSufficientlyReplicatedByHost("datanode_host1"));
}

