@Test
public void testReplicasNotOutputIfError() throws IOException {
    Mockito.when(scmClient.getContainerReplicas(anyLong())).thenThrow(new IOException("Error getting Replicas"));
    cmd = new InfoSubcommand();
    CommandLine c = new CommandLine(cmd);
    c.parseArgs("1");
    cmd.execute(scmClient);
    // Ensure we have no lines for Replicas:
    List<LoggingEvent> logs = appender.getLog();
    List<LoggingEvent> replica = logs.stream().filter(m -> m.getRenderedMessage().matches("(?s)^Replicas:.*")).collect(Collectors.toList());
    Assertions.assertEquals(0, replica.size());
    // Ensure we have an error logged:
    List<LoggingEvent> error = logs.stream().filter(m -> m.getLevel() == Level.ERROR).collect(Collectors.toList());
