@Test
public void ensureTermAndDeadlineOnCommands() throws IOException, TimeoutException {
    OzoneStorageContainerManager scm = Mockito.mock(OzoneStorageContainerManager.class);
    ReplicateContainerCommand command = ReplicateContainerCommand.forTest(1);
    command.setTerm(5L);
    command.setDeadline(1234L);
    StorageContainerDatanodeProtocolProtos.SCMCommandProto proto = SCMDatanodeProtocolServer.getCommandResponse(command, scm);
    Assert.assertEquals(StorageContainerDatanodeProtocolProtos.SCMCommandProto.Type.replicateContainerCommand, proto.getCommandType());
    Assert.assertEquals(5L, proto.getTerm());
    Assert.assertEquals(1234L, proto.getDeadlineMsSinceEpoch());
}

@Test
public void testGetKeyProvider() throws Exception {
    KeyProvider kp1 = store.getKeyProvider();
    KeyProvider kpSpy = Mockito.spy(kp1);
    Assert.assertNotEquals(kpSpy, kp1);
    Cache<URI, KeyProvider> cacheSpy = ((RpcClient) store.getClientProxy()).getKeyProviderCache();
    cacheSpy.put(store.getKeyProviderUri(), kpSpy);
    KeyProvider kp2 = store.getKeyProvider();
    Assert.assertEquals(kpSpy, kp2);
    // Verify the spied key provider is closed upon ozone client close
    ozClient.close();
    Mockito.verify(kpSpy).close();
    KeyProvider kp3 = ozClient.getObjectStore().getKeyProvider();
    Assert.assertNotEquals(kp3, kpSpy);
    // Restore ozClient and store
    TestOzoneRpcClient.setOzClient(OzoneClientFactory.getRpcClient(conf));
    TestOzoneRpcClient.setStore(ozClient.getObjectStore());
}

