public static void setUp() throws Exception {
    CLIENT.getObjectStore().createS3Bucket(OzoneConsts.S3_BUCKET);
    OzoneBucket bucket = CLIENT.getObjectStore().getS3Bucket(OzoneConsts.S3_BUCKET);
    byte[] keyContent = EXISTING_KEY_CONTENT.getBytes(UTF_8);
    try (OutputStream stream = bucket.createKey(EXISTING_KEY, keyContent.length, ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, ReplicationFactor.THREE), new HashMap<>())) {
        stream.write(keyContent);
    }
    sourceKeyLastModificationTime = CLIENT.getObjectStore().getS3Bucket(OzoneConsts.S3_BUCKET).getKey(EXISTING_KEY).getModificationTime().toEpochMilli();
    beforeSourceKeyModificationTimeStr = OzoneUtils.formatTime(sourceKeyLastModificationTime - 1000);
    afterSourceKeyModificationTimeStr = OzoneUtils.formatTime(sourceKeyLastModificationTime + DELAY_MS);
    futureTimeStr = OzoneUtils.formatTime(sourceKeyLastModificationTime + 1000 * 60 * 24);
    // Make sure DELAY_MS has passed, otherwise
    //  afterSourceKeyModificationTimeStr will be in the future
    //  and thus invalid
    long currentTime = System.currentTimeMillis();
    long sleepMs = sourceKeyLastModificationTime + DELAY_MS - currentTime;
    if (sleepMs > 0) {
        Thread.sleep(sleepMs);
